using System.Collections.ObjectModel;
using System.Text;

namespace Netrunner.Cards;

/// <summary>
/// The mode and authenticated bytes generated by DATA-400 are exposed through
/// this small, read-only runtime boundary.  No caller needs to know where the
/// local source snapshot lived, and no runtime path performs a network fetch.
/// </summary>
public static class CardDataResource
{
    public const string OfficialMode = "official";
    public const string SyntheticMode = "synthetic";

    private static readonly Lazy<CardDataSet> Embedded = new(
        LoadEmbeddedCore,
        LazyThreadSafetyMode.ExecutionAndPublication);

    private static readonly Lazy<CardDataSet?> EmbeddedElevation = new(
        LoadEmbeddedElevationCore,
        LazyThreadSafetyMode.ExecutionAndPublication);

    private static readonly Lazy<CardDataSet?> EmbeddedVantagePoint = new(
        LoadEmbeddedVantagePointCore,
        LazyThreadSafetyMode.ExecutionAndPublication);

    /// <summary>The authenticated source mode selected during the build.</summary>
    public static string EmbeddedMode => GeneratedCardData.Mode;

    /// <summary>
    /// The pack codes embedded in this build, in pool order. A synthetic
    /// build embeds only its fixture pack; an official build embeds System
    /// Gateway, Elevation and Vantage Point, each authenticated by its own manifest.
    /// </summary>
    public static IReadOnlyList<string> EmbeddedPackCodes =>
        [
            LoadEmbedded().Manifest.PackCode,
            .. EmbeddedElevation.Value is null ? Array.Empty<string>() : [OfficialCardPacks.ElevationCode],
            .. EmbeddedVantagePoint.Value is null ? Array.Empty<string>() : [OfficialCardPacks.VantagePointCode],
        ];

    /// <summary>Whether this build embeds the named pack.</summary>
    public static bool HasEmbeddedPack(string packCode) =>
        EmbeddedPackCodes.Contains(packCode, StringComparer.Ordinal);

    /// <summary>
    /// Loads one embedded pack by code. The primary pack is the payload
    /// <see cref="LoadEmbedded"/> returns; Elevation and Vantage Point are further
    /// packs present only in official builds.
    /// </summary>
    public static CardDataSet LoadEmbeddedPack(string packCode)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(packCode);
        CardDataSet primary = LoadEmbedded();
        if (string.Equals(primary.Manifest.PackCode, packCode, StringComparison.Ordinal))
        {
            return primary;
        }

        if (string.Equals(packCode, OfficialCardPacks.ElevationCode, StringComparison.Ordinal)
            && EmbeddedElevation.Value is { } elevation)
        {
            return elevation;
        }

        if (string.Equals(packCode, OfficialCardPacks.VantagePointCode, StringComparison.Ordinal)
            && EmbeddedVantagePoint.Value is { } vantagePoint)
        {
            return vantagePoint;
        }

        throw new CardDataValidationException(
            $"DATA-400: pack '{packCode}' is not embedded in this {EmbeddedMode} build.");
    }

    /// <summary>
    /// Loads a pool of embedded packs as one set. Each pack keeps its own
    /// manifest under <see cref="CardDataSet.Packs"/>.
    /// </summary>
    public static CardDataSet LoadEmbeddedPool(IReadOnlyList<string> packCodes)
    {
        ArgumentNullException.ThrowIfNull(packCodes);
        return CardDataSet.Combine(packCodes.Select(LoadEmbeddedPack).ToArray());
    }

    /// <summary>Loads every embedded pack as one pool.</summary>
    public static CardDataSet LoadEmbeddedPool() => LoadEmbeddedPool(EmbeddedPackCodes);

    /// <summary>
    /// Gets the generated card snapshot after validating its checksum,
    /// manifest, schema, and record constraints. The result is immutable.
    /// </summary>
    public static CardDataSet LoadEmbedded() => Embedded.Value;

    /// <summary>
    /// Attempts to load generated content without throwing at a client
    /// boundary. Diagnostics deliberately identify the failing validation,
    /// while never suggesting a runtime network fetch.
    /// </summary>
    public static bool TryLoadEmbedded(
        out CardDataSet? data,
        out string diagnostic)
    {
        try
        {
            data = LoadEmbedded();
            diagnostic = $"DATA-400: embedded {EmbeddedMode} card data loaded "
                + $"({data.Cards.Count} cards, {data.Manifest.OutputSha256}).";
            return true;
        }
        catch (Exception exception) when (exception is CardDataValidationException or InvalidOperationException)
        {
            data = null;
            diagnostic = $"DATA-400: embedded card data is unavailable: {exception.Message}";
            return false;
        }
    }

    /// <summary>
    /// Loads bytes from a generated payload. This overload is useful to build
    /// and content-lane tests that need to exercise corrupt/stale bytes
    /// without writing to the ignored source directory.
    /// </summary>
    public static CardDataSet LoadBytes(
        ReadOnlySpan<byte> cardsBytes,
        ReadOnlySpan<byte> manifestBytes,
        ReadOnlySpan<byte> copyrightBytes,
        bool requireOfficialGateway = false)
    {
        CardDataManifest manifest = CardDataJson.ParseManifest(manifestBytes);
        CardDataValidator.ValidateManifest(manifest, requireOfficialGateway);

        string actualSha = CardDataJson.ComputeSha256Hex(cardsBytes);
        if (!string.Equals(actualSha, manifest.OutputSha256, StringComparison.Ordinal))
        {
            throw new CardDataValidationException(
                "DATA-400: embedded normalized card checksum mismatch: "
                + $"manifest has '{manifest.OutputSha256}', actual bytes have '{actualSha}'.");
        }

        IReadOnlyList<NormalizedCardDefinition> cards = CardDataJson.ParseCards(cardsBytes);
        CardDataValidator.Validate(cards, manifest, requireOfficialGateway);
        ValidateCopyright(copyrightBytes);
        return new CardDataSet(cards, manifest);
    }

    /// <summary>Returns a detached copy of the generated normalized bytes.</summary>
    public static byte[] CopyEmbeddedCardsBytes() => Decode(GeneratedCardData.CardsBase64, "cards");

    /// <summary>Returns a detached copy of the generated manifest bytes.</summary>
    public static byte[] CopyEmbeddedManifestBytes() => Decode(GeneratedCardData.ManifestBase64, "manifest");

    private static CardDataSet LoadEmbeddedCore()
    {
        byte[] cards = CopyEmbeddedCardsBytes();
        byte[] manifest = CopyEmbeddedManifestBytes();
        byte[] copyright = Decode(GeneratedCardData.CopyrightBase64, "copyright");
        bool requireOfficial = string.Equals(EmbeddedMode, OfficialMode, StringComparison.Ordinal);
        if (!requireOfficial && !string.Equals(EmbeddedMode, SyntheticMode, StringComparison.Ordinal))
        {
            throw new CardDataValidationException(
                $"DATA-400: generated card-data mode '{EmbeddedMode}' is unsupported.");
        }

        return LoadBytes(cards, manifest, copyright, requireOfficial);
    }

    private static CardDataSet? LoadEmbeddedElevationCore()
    {
        if (GeneratedCardData.ElevationCardsBase64.Length == 0
            && GeneratedCardData.ElevationManifestBase64.Length == 0
            && GeneratedCardData.ElevationCopyrightBase64.Length == 0)
        {
            return null;
        }

        CardDataSet elevation = LoadBytes(
            Decode(GeneratedCardData.ElevationCardsBase64, "Elevation cards"),
            Decode(GeneratedCardData.ElevationManifestBase64, "Elevation manifest"),
            Decode(GeneratedCardData.ElevationCopyrightBase64, "Elevation copyright"),
            requireOfficialGateway: true);
        if (!string.Equals(elevation.Manifest.PackCode, OfficialCardPacks.ElevationCode, StringComparison.Ordinal))
        {
            throw new CardDataValidationException(
                $"DATA-400: the embedded Elevation payload is pack '{elevation.Manifest.PackCode}'.");
        }

        return elevation;
    }

    private static CardDataSet? LoadEmbeddedVantagePointCore()
    {
        if (GeneratedCardData.VantagePointCardsBase64.Length == 0
            && GeneratedCardData.VantagePointManifestBase64.Length == 0
            && GeneratedCardData.VantagePointCopyrightBase64.Length == 0)
        {
            return null;
        }

        CardDataSet vantagePoint = LoadBytes(
            Decode(GeneratedCardData.VantagePointCardsBase64, "Vantage Point cards"),
            Decode(GeneratedCardData.VantagePointManifestBase64, "Vantage Point manifest"),
            Decode(GeneratedCardData.VantagePointCopyrightBase64, "Vantage Point copyright"),
            requireOfficialGateway: true);
        if (!string.Equals(vantagePoint.Manifest.PackCode, OfficialCardPacks.VantagePointCode, StringComparison.Ordinal))
        {
            throw new CardDataValidationException(
                $"DATA-400: the embedded Vantage Point payload is pack '{vantagePoint.Manifest.PackCode}'.");
        }

        return vantagePoint;
    }

    private static byte[] Decode(string value, string description)
    {
        try
        {
            return Convert.FromBase64String(value);
        }
        catch (FormatException exception)
        {
            throw new CardDataValidationException(
                $"DATA-400: generated {description} payload is corrupt (invalid base64).",
                exception);
        }
    }

    private static void ValidateCopyright(ReadOnlySpan<byte> bytes)
    {
        if (bytes.Length == 0)
        {
            throw new CardDataValidationException(
                "DATA-400: embedded source copyright notice must not be empty.");
        }

        try
        {
            _ = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true)
                .GetString(bytes);
        }
        catch (DecoderFallbackException exception)
        {
            throw new CardDataValidationException(
                "DATA-400: embedded source copyright notice is not valid UTF-8.",
                exception);
        }
    }
}

/// <summary>
/// Convenience catalog for consumers that need metadata lookup by stable
/// definition code. It takes a snapshot at construction and never exposes a
/// mutable source collection.
/// </summary>
[System.Diagnostics.CodeAnalysis.SuppressMessage(
    "Naming",
    "CA1710:Identifiers should have correct suffix",
    Justification = "Catalog is the domain term for this immutable lookup boundary.")]
public sealed class CardMetadataCatalog : IReadOnlyDictionary<string, NormalizedCardDefinition>
{
    private readonly IReadOnlyDictionary<string, NormalizedCardDefinition> _cards;

    public CardMetadataCatalog(IEnumerable<NormalizedCardDefinition> cards)
    {
        ArgumentNullException.ThrowIfNull(cards);
        var values = cards.ToArray();
        if (values.Length == 0)
        {
            throw new CardDataValidationException("Card metadata catalog must contain at least one card.");
        }

        // A pool spans packs; each pack's records are validated (and kept in
        // their normalized order) on their own.
        foreach (IGrouping<string, NormalizedCardDefinition> pack in values.GroupBy(static card => card.SetCode))
        {
            CardDataValidator.ValidateRecords(pack.ToArray(), pack.Key);
        }

        var byCode = new Dictionary<string, NormalizedCardDefinition>(StringComparer.Ordinal);
        foreach (NormalizedCardDefinition card in values)
        {
            if (!byCode.TryAdd(card.Code, card))
            {
                throw new CardDataValidationException($"Duplicate normalized card code '{card.Code}'.");
            }
        }

        _cards = new ReadOnlyDictionary<string, NormalizedCardDefinition>(byCode);
    }

    public static CardMetadataCatalog Embedded() => new(CardDataResource.LoadEmbedded().Cards);

    public NormalizedCardDefinition this[string key] => _cards[key];

    public IEnumerable<string> Keys => _cards.Keys;

    public IEnumerable<NormalizedCardDefinition> Values => _cards.Values;

    public int Count => _cards.Count;

    public bool ContainsKey(string key) => _cards.ContainsKey(key);

    public bool TryGetValue(string key, out NormalizedCardDefinition value) =>
        _cards.TryGetValue(key, out value!);

    public IEnumerator<KeyValuePair<string, NormalizedCardDefinition>> GetEnumerator() =>
        _cards.GetEnumerator();

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() =>
        GetEnumerator();
}
